class HitCounter:
    def __init__(self):
        self.hits = []

    def hit(self, timestamp):
        self.hits.append(timestamp)

    def get_hits(self, timestamp):
        count = 0
        for t in self.hits:
            if t > timestamp - 300:
                count += 1
        return count


if __name__ == "__main__":
    counter = HitCounter()
    counter.hit(1)
    counter.hit(2)
    counter.hit(3)
    print(counter.get_hits(4))
    counter.hit(300)
    print(counter.get_hits(300))
    print(counter.get_hits(301))

